      // Read the actual current URL and title from the iframe after load
      this.readIframeUrl()
      this.$emit('loaded')
    },
    // Read URL and title directly from iframe contentWindow after navigation
    readIframeUrl() {
      try {
        const iframeEl = this.$refs.iframe?.$el || this.$refs.iframe
